./gradlew --no-daemon --offline testDebugUnitTest --tests 'org.altbeacon.beacon.SettingsTest' --tests 'org.altbeacon.beacon.SettingsJavaTest' || true
python3 - <<'PY'
import glob, xml.etree.ElementTree as ET
for f in sorted(glob.glob('lib/build/test-results/testDebugUnitTest/*.xml')):
    root = ET.parse(f).getroot()
    for tc in root.iter('testcase'):
        name = tc.get('classname') + '::' + tc.get('name')
        if tc.find('failure') is not None or tc.find('error') is not None:
            status = 'FAILED'
        elif tc.find('skipped') is not None:
            status = 'SKIPPED'
        else:
            status = 'PASSED'
        print(name, status)
PY
